<script setup>
import { Link, useForm } from '@inertiajs/vue3'
import AppLayout from '@/Layouts/AppLayout.vue'
import PrimaryButton from '@/Components/PrimaryButton.vue'
import InputError from '@/Components/InputError.vue'
import { ref } from 'vue'
defineProps({ requests: Object })
const selected = ref(null)
const form = useForm({ response: '' })
function select(item) { selected.value = item.id; form.response = item.response ?? ''; form.clearErrors() }
function submit() { form.patch(route('admin.account-deletions.update', selected.value), {preserveScroll:true, onSuccess:() => { selected.value = null }}) }
</script>
<template><AppLayout title="Solicitudes de privacidad"><div class="mx-auto max-w-4xl space-y-5"><div class="rounded-2xl bg-white p-6"><h2 class="text-xl font-bold">Solicitudes de eliminación</h2><p class="mt-2 text-sm text-slate-600">Atiende el plazo legal de respuesta de 10 días hábiles. Revisa el estado actual, la retención justificada y las obligaciones con terceros. Esta pantalla registra una respuesta; no ejecuta ni certifica una eliminación definitiva.</p></div>
  <p v-if="!requests.data.length" class="rounded-2xl bg-white p-6 text-slate-500">No hay solicitudes registradas.</p>
  <article v-for="item in requests.data" :key="item.id" class="rounded-2xl border border-slate-100 bg-white p-5 sm:p-6"><div class="flex flex-wrap justify-between gap-3"><h3 class="font-bold">{{ item.user.name }}</h3><span class="text-xs font-semibold text-brand-700">{{ item.status === 'responded' ? 'Respuesta registrada' : 'Pendiente de revisión' }}</span></div><p class="mt-1 break-all text-sm text-slate-500">{{ item.user.email }} · {{ new Date(item.created_at).toLocaleDateString('es-PE') }}</p><p class="mt-2 break-all text-xs text-slate-500">{{ item.reference }}</p><p class="mt-4 text-sm text-slate-600">Al solicitar: {{ item.snapshot.pending_classes }} clases pendientes · {{ item.snapshot.active_requests }} solicitudes activas · {{ item.snapshot.students }} alumnos · {{ item.snapshot.credits_available }} créditos disponibles · {{ item.snapshot.credits_reserved }} reservados · {{ item.snapshot.pending_payments }} pagos pendientes.</p><p class="mt-2 text-xs text-amber-800">Esta es la fotografía al solicitar; verifica las operaciones actuales antes de decidir.</p><p v-if="item.response && selected !== item.id" class="mt-4 whitespace-pre-wrap text-sm">{{ item.response }}</p>
    <button v-if="selected !== item.id" @click="select(item)" class="mt-4 min-h-11 rounded-xl border border-brand-200 px-4 text-sm font-bold text-brand-700">Registrar respuesta</button><form v-else @submit.prevent="submit" class="mt-5"><label :for="`response-${item.id}`" class="block text-sm font-bold">Respuesta para el titular y justificación de conservación</label><textarea :id="`response-${item.id}`" v-model="form.response" rows="5" required minlength="20" maxlength="5000" class="mt-2 w-full rounded-xl border-slate-300" /><InputError :message="form.errors.response" /><div class="mt-3 flex gap-4"><PrimaryButton :disabled="form.processing">Guardar respuesta</PrimaryButton><button type="button" @click="selected = null" :disabled="form.processing">Cancelar</button></div></form>
  </article><nav aria-label="Paginación" class="flex flex-wrap gap-3"><Link v-if="requests.prev_page_url" :href="requests.prev_page_url">Anterior</Link><Link v-if="requests.next_page_url" :href="requests.next_page_url">Siguiente</Link></nav></div></AppLayout></template>
